                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        String tokenN = fs.next();
        if (tokenN == null) return;
        int n = Integer.parseInt(tokenN);
        int m = fs.nextInt();

        List<List<Integer>> treeC = new ArrayList<>(n + 1);
        for (int i = 0; i <= n; i++) {
            treeC.add(new ArrayList<>());
        }
        for (int i = 0; i < n - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            treeC.get(u).add(v);
            treeC.get(v).add(u);
        }

        List<List<Integer>> treeQ = new ArrayList<>(m + 1);
        for (int i = 0; i <= m; i++) {
            treeQ.add(new ArrayList<>());
        }
        for (int i = 0; i < m - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            treeQ.get(u).add(v);
            treeQ.get(v).add(u);
        }

        int centerC = findCenter(treeC, n);
        int centerQ = findCenter(treeQ, m);

        System.out.println(centerC + " " + centerQ);
    }

    private static int findCenter(List<List<Integer>> adj, int size) {
        int[] dist = new int[size + 1];
        int[] parent = new int[size + 1];

        // 1ª BFS a partir do nó 1
        int u = bfs(1, adj, size, dist, parent);

        // 2ª BFS a partir do nó u
        int v = bfs(u, adj, size, dist, parent);

        // Reconstrói o caminho de v até u
        List<Integer> path = new ArrayList<>();
        int curr = v;
        while (curr != -1) {
            path.add(curr);
            curr = parent[curr];
        }

        // O centro é o vértice no meio do caminho diametral
        return path.get(path.size() / 2);
    }

    private static int bfs(int start, List<List<Integer>> adj, int size, int[] dist, int[] parent) {
        Arrays.fill(dist, -1);
        Queue<Integer> q = new ArrayDeque<>();

        dist[start] = 0;
        parent[start] = -1;
        q.add(start);

        int farthestNode = start;

        while (!q.isEmpty()) {
            int u = q.poll();
            if (dist[u] > dist[farthestNode]) {
                farthestNode = u;
            }

            for (int v : adj.get(u)) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.add(v);
                }
            }
        }

        return farthestNode;
    }
}
